const INITIAL_STATE: Record<string, string> = {
  Zef: "nex",
  Tal: "nex",
};

function withEntityState(
  state: WorldStateHandle,
  changes: Record<string, string>
): WorldStateHandle {
  return {
    entities: {
      ...state.entities,
      ...changes,
    },
  };
}

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return { entities: { ...INITIAL_STATE } };
  },

  applyOperation(state, operationDisplayName) {
    switch (operationDisplayName) {
      case "kindleZef":
        return {
          success: true,
          newState: withEntityState(state, { Zef: "pex" }),
        };
      case "kindleTal":
        return {
          success: true,
          newState: withEntityState(state, { Tal: "pex" }),
        };
      case "kindleBoth":
        return {
          success: true,
          newState: withEntityState(state, {
            Zef: "pex",
            Tal: "pex",
          }),
        };
      default:
        return {
          success: false,
          error: `Unknown operation: ${operationDisplayName}`,
        };
    }
  },

  getEntityState(state, entityDisplayName) {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state.entities };
  },
};
